def remove(self, sku, quantity):
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    current = self._stock.get(sku, 0)
    if quantity > current:
        raise ValueError(f"only {current} of {sku} in stock")
    self._stock[sku] = current - quantity
